(()=>{let theme='light';try{theme=localStorage.getItem('wortreise-theme')||'light'}catch{}document.documentElement.dataset.theme=theme;function apply(value){document.documentElement.dataset.theme=value;try{localStorage.setItem('wortreise-theme',value)}catch{}const button=document.querySelector('#theme-toggle');if(button){button.textContent=value==='dark'?'☾ Dark':'☀ Light';button.setAttribute('aria-pressed',String(value==='dark'));button.title='Switch to '+(value==='dark'?'light':'dark')+' theme'}document.querySelector('meta[name="theme-color"]')?.setAttribute('content',value==='dark'?'#17213b':'#f6f5ff')}
document.addEventListener('DOMContentLoaded',()=>{const button=document.createElement('button');button.id='theme-toggle';button.className='theme-toggle';button.setAttribute('aria-label','Toggle dark theme');button.onclick=()=>apply(document.documentElement.dataset.theme==='dark'?'light':'dark');document.querySelector('aside').append(button);apply(theme)})})();

document.addEventListener('DOMContentLoaded',()=>{const sync=()=>{const nav=document.querySelector('aside'),dock=document.querySelector('.voice-dock');document.documentElement.style.setProperty('--nav-height',(nav?.getBoundingClientRect().height||64)+'px');document.documentElement.style.setProperty('--dock-height',(dock?.getBoundingClientRect().height||90)+'px')};const observer=new ResizeObserver(sync);observer.observe(document.querySelector('aside'));if(document.querySelector('.voice-dock'))observer.observe(document.querySelector('.voice-dock'));sync()});
